examples.setup:
val goals = listOf(
    MonarchGoal(id = "o1", title = "Ship the mobile app", progress = 0.1f, status = MonarchGoalStatus.OffTrack),
    MonarchGoal(id = "k1", parentId = "o1", title = "Beta with 50 testers", progress = 0f, status = MonarchGoalStatus.NotStarted),
)
var expanded by remember { mutableStateOf(emptySet<String>()) }

examples.code:
@OptIn(ExperimentalMonarchApi::class)
MonarchGoalTree(
    goals = goals,
    expandIcon = { Text("›") },
    expanded = expanded,
    onExpandedChange = { expanded = it },
) { goal ->
    var open by remember { mutableStateOf(false) }
    MonarchButton(text = "More", onClick = { open = true }, variant = MonarchButtonVariant.Ghost, size = MonarchButtonSize.Sm)
    MonarchMenu(expanded = open, onDismissRequest = { open = false }) {
        MonarchMenuItem(text = "Check in on ${goal.title}", onClick = { open = false })
    }
}
